# Let me find connected components for each color (excluding background 3)
from collections import deque

def find_components(grid, color):
    height = len(grid)
    width = len(grid[0])
    visited = set()
    components = []

    def bfs(start):
        comp = [start]
        q = deque([start])
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    comp.append((nr, nc))
                    q.append((nr, nc))
        return comp

    for r in range(height):
        for c in range(width):
            if grid[r][c] == color and (r, c) not in visited:
                comp = bfs((r, c))
                components.append(comp)
    return components

