def count_other_occurrences(grid):
    h, w = len(grid), len(grid[0])
    pos_by_color = defaultdict(list)
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 3:
                pos_by_color[val].append((r,c))

    result = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 3:
                # Count how many other cells have this same value
                others = len(pos_by_color[val]) - 1
                result[r][c] = min(others + 1, 9)  # Clamp to 9

    return result

